draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 20, H/2 + Math.sin(t) * 10);
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t) * 100, H - 50, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 100, H - 50);
  ctx.lineTo(W/2 + Math.cos(t) * 100 + Math.sin(t) * 30, H - 50 + Math.cos(t) * 10);
  ctx.stroke();

  // butterfly
  ctx.beginPath();
  ctx.arc(W - 50, H/2 + Math.sin(t) * 50, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 50, H/2 + Math.sin(t) * 50);
  ctx.lineTo(W - 50 + Math.cos(t) * 20, H/2 + Math.sin(t) * 50 + Math.sin(t) * 10);
  ctx.stroke();

  ctx.restore();
}
